/**
 * 能力面板 · Tools 域（v13 R3 / 帧 06；v21 纳入可见性与工作区默认）。
 *
 * Tools 是**全局工具注册**：一个插件 = 一个开关单元，无单工具开关。两栏布局：
 *   - 左：插件单元列表；
 *   - 右：插件详情 + 只读工具清单（手风琴；schema 由 `tools.inspect` 懒加载）。
 *
 * 三层开关（v21，与 Skills / MCP 同构）：
 *   1. **可见性（全局唯一控制，按工作区）**：全局视图行内标签 + 「可见范围」编辑
 *      （`overrides.globalGet().visibility.tools` / `overrides.setVisibility`）；
 *   2. **每工作区默认开/关**：可见性弹层里按工作区配置；某工作区没有单独配置时
 *      走兜底 `!全局默认关闭(unit)`（`capability-global-overrides.json` 的 `tools`
 *      ∪ legacy `tools-global.json`，宿主已合并进行字段 `defaultEnabled`）；
 *   3. **工作区覆盖**：工作区视图的行尾开关写项目三态
 *      （`overrides.toggle("tools", unit, {enabled})` → `tools` / `enabledTools`）。
 *
 * 全局视图的行尾开关仍是**全局默认兜底**（`tools.setGlobalEnabled`，写统一全局文件）；
 * 不可见行的默认开关禁用并标「不可见 · 不参与默认」。
 *
 * @module dsh-capability-settings/client/tools-panel
 */

import { memo, useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { CSSProperties, KeyboardEvent as ReactKeyboardEvent } from "react";
import type {
  CapabilityPanelApi,
  ClientCapabilityVisibility,
  ClientGlobalOverrides,
  ClientOverrides,
  ClientToolInspectTool,
  ClientToolsList,
  ClientToolsUnit,
} from "./api.js";
import { ToolParameterTable, toolParameters } from "./tool-schema.js";
import { useAsyncList } from "./panel-common.js";
import {
  EMPTY_VISIBILITY_SETS,
  VisibilityDetailFields,
  VisibilityRowMeta,
  isRowInvisible,
  safeGlobalGet,
  safeOverridesGet,
  visibilityEntryOf,
  visibilityModeOf,
  visibleWorkspaceCountOf,
  workspaceDefaultOf,
  workspaceOverrideOf,
  type WorkspaceOverrideState,
} from "./visibility.js";

/** 详情标题右侧标签行的排版（与 mcp-panel 的 HEAD_TAGS_STYLE 同形）。 */
const HEAD_TAGS_STYLE: CSSProperties = { display: "inline-flex", alignItems: "center", gap: 6, flex: "none" };

/** 详情底部弱说明的上外边距。 */
const NOTE_STYLE: CSSProperties = { margin: "10px 0 0" };

/**
 * 单元的**全局默认**开关：新宿主给 `defaultEnabled`；旧宿主/夹具只有单层
 * `enabledInSession` 时回落到它，再缺省按默认开启（与宿主 `TOOLS_DEFAULT_ENABLED` 一致）。
 */
function defaultEnabledOf(unit: ClientToolsUnit): boolean {
  return unit.defaultEnabled ?? unit.enabledInSession ?? true;
}

/** 未识别单元的琥珀标签类（复用既有 warn 标签）。 */
function unitTagClass(unit: ClientToolsUnit): string {
  return unit.kind === "unattributed" ? "skp-tag skp-tag-warn" : "skp-tag skp-tag-plugin";
}

/**
 * 单元排序：保持宿主枚举顺序（帧 06 的插件顺序来自运行时注册顺序），只把
 * 来源未识别恒排最后（UX v1.8 §5.4 的分组语义）。
 */
function sortUnits(units: ClientToolsUnit[]): ClientToolsUnit[] {
  return [...units.filter((unit) => unit.kind !== "unattributed"), ...units.filter((unit) => unit.kind === "unattributed")];
}

/** 路径最后一段（工作区名）；空串/纯分隔符回退为原串。 */
function baseName(path: string): string {
  const trimmed = path.replace(/[\\/]+$/, "");
  const at = Math.max(trimmed.lastIndexOf("/"), trimmed.lastIndexOf("\\"));
  return at >= 0 ? trimmed.slice(at + 1) || trimmed : trimmed || path;
}

/** 归属依据的人话标签（task-32：运行时/包扫描/人工映射/名字推测/命名空间/未识别）。 */
function attributionLabel(unit: ClientToolsUnit): string {
  switch (unit.attribution.matchedBy) {
    case "runtime":
      return "运行时捕获";
    case "literal":
      return "包扫描";
    case "table":
    case "prefix":
    case "exact":
      return "人工映射";
    case "similarity":
      return "名字推测";
    case "namespace":
      return "命名空间";
    default:
      return "未识别";
  }
}

/** true = 来源含推测成分（UI 加琥珀「推测」标识与核对提示）。 */
function attributionIsSpeculative(unit: ClientToolsUnit): boolean {
  const attribution = unit.attribution;
  // 「运行时捕获」分两档：调用方身份（高置信）与注册栈兜底（中置信，标推测）。
  const runtimeFallback = attribution.matchedBy === "runtime" && attribution.confidence === "medium";
  return (
    attribution.matchedBy === "similarity" ||
    runtimeFallback ||
    attribution.ambiguous === true ||
    attribution.conflictsWithTable === true
  );
}

/** 详情「来源判定」的补充说明（依据原文 / 冲突 / 置信度 / 多来源合并）。 */
function attributionDetail(unit: ClientToolsUnit): string | undefined {
  const attribution = unit.attribution;
  const parts: string[] = [];
  const pattern = attribution.pattern ?? attribution.packageName;
  if (attribution.matchedBy === "prefix" && pattern !== undefined) parts.push(`前缀 ${pattern} → ${unit.name}（插件清单映射表）`);
  else if (attribution.matchedBy === "exact" && pattern !== undefined) parts.push(`精确匹配 ${pattern} → ${unit.name}（插件清单映射表）`);
  else if (pattern !== undefined && pattern !== unit.name) parts.push(pattern);
  if (attribution.conflictsWithTable === true) parts.push("与人工映射冲突");
  if (attribution.ambiguous === true) parts.push("存在多个候选");
  if (attribution.mixed === true) parts.push("多来源合并");
  if (attribution.matchedBy === "runtime" && attribution.confidence === "medium") parts.push("注册栈兜底");
  const confidence = attribution.confidence;
  if (typeof confidence === "number" && Number.isFinite(confidence)) {
    // 旧数字口径：0–1 → 百分比（adapter 已归一到 0–1）。
    parts.push(`置信度 ${Math.round(Math.max(0, Math.min(1, confidence)) * 100)}%`);
  } else if (confidence === "high") {
    parts.push("高置信");
  } else if (confidence === "medium") {
    parts.push("中置信");
  } else if (confidence === "low") {
    parts.push("低置信");
  }
  return parts.length > 0 ? parts.join(" · ") : undefined;
}

/**
 * 一个工具的手风琴行：行 = 工具名 + `N 个参数/无参数`；展开后显示说明、
 * 参数表（参数/类型/必填/说明）与可折叠的原始 JSON（`parameters` pretty）。
 */
function ToolAccordionItem({ tool, open, onToggle }: { tool: ClientToolInspectTool; open: boolean; onToggle(): void }) {
  const [rawOpen, setRawOpen] = useState(false);
  const parameters = useMemo(() => toolParameters(tool.parameters), [tool.parameters]);
  const description = tool.description?.trim() ?? "";
  return (
    <div className={open ? "skp-tool-item skp-tool-item-open" : "skp-tool-item"} role="listitem">
      <button type="button" className="skp-tool-trigger" aria-expanded={open} title={tool.name} onClick={onToggle}>
        <span className="skp-tool-chevron" aria-hidden="true">
          {open ? "▾" : "▸"}
        </span>
        <code className="skp-tool-name">{tool.name}</code>
        <span className="skp-tool-count">{parameters.length > 0 ? `${parameters.length} 个参数` : "无参数"}</span>
      </button>
      {open && (
        <div className="skp-tool-body">
          {description.length > 0 && <p className="skp-tool-desc">{description}</p>}
          <ToolParameterTable parameters={parameters} />
          <div className="skp-tools-raw">
            <button type="button" className="skp-link-btn" aria-expanded={rawOpen} onClick={() => setRawOpen((value) => !value)}>
              {rawOpen ? "收起原始 JSON" : "查看原始 JSON"}
            </button>
            {rawOpen && <pre className="skp-tools-raw-json">{JSON.stringify(tool.parameters ?? {}, null, 2)}</pre>}
          </div>
        </div>
      )}
    </div>
  );
}

/** 单个单元的 schema 懒加载状态（按 unit 缓存）。 */
type InspectState =
  | { status: "loading" }
  | { status: "ready"; tools: ClientToolInspectTool[] }
  | { status: "error"; message: string };

/**
 * Tools 列表单行（v21.3，`React.memo`）：避免切作用域 / 选中 / 刷新提示时整表重渲。
 * 行状态（checked/disabled/invisible/override）由父级计算后以原始值传入。
 */
const ToolListRow = memo(function ToolListRow({
  unit,
  active,
  scope,
  projectName,
  projects,
  visibilityEntry,
  globalOff,
  checked,
  disabled,
  invisible,
  override,
  busy,
  rowRefs,
  onSelect,
  onToggle,
  onKeyDown,
}: {
  unit: ClientToolsUnit;
  active: boolean;
  scope: "global" | "workspace";
  projectName?: string;
  projects: Array<{ path: string; title?: string }>;
  visibilityEntry?: ClientCapabilityVisibility;
  globalOff: boolean;
  checked: boolean;
  disabled: boolean;
  invisible: boolean;
  override: WorkspaceOverrideState;
  busy: boolean;
  rowRefs: { current: Map<string, HTMLElement> };
  onSelect(unit: ClientToolsUnit): void;
  onToggle(unit: ClientToolsUnit, next: boolean): void;
  onKeyDown(event: ReactKeyboardEvent<HTMLElement>, unit: string): void;
}) {
  const locked = unit.lockedReason !== undefined;
  const visibilityMeta =
    scope === "global" ? (
      <VisibilityRowMeta
        entry={visibilityEntry}
        workspaces={projects}
        globalOff={globalOff}
        mode={unit.visibilityMode ?? visibilityModeOf(visibilityEntry)}
        count={unit.visibleWorkspaceCount ?? visibleWorkspaceCountOf(visibilityEntry, projects)}
        invisible={invisible}
        summaryClassName="skp-vis-summary"
      />
    ) : (
      override !== "inherit" && (
        <span
          className="skp-tag skp-tag-warn"
          title={override === "on" ? "本工作区显式打开（覆盖全局的每工作区默认）" : "本工作区显式关闭（覆盖全局的每工作区默认）"}
        >
          已覆盖
        </span>
      )
    );
  const switchLabel = invisible
    ? "不可见 · 不参与默认"
    : scope === "global"
      ? "全局默认"
      : `默认 · ${override === "inherit" ? "跟随全局" : "已覆盖"}`;
  const switchTitle = invisible
    ? "该单元对所有工作区都不可见：不参与默认开关；先在「可见范围」里打开可见性"
    : locked
      ? (unit.lockedReason ?? "该插件无法开关")
      : scope === "global"
        ? defaultEnabledOf(unit)
          ? "关闭：关闭后全局默认不可用；仍可在对话首屏为单个对话单独开启"
          : "开启：全局默认可用（仍可在对话首屏为单个对话单独关闭）"
        : checked
          ? "关闭：仅此工作区默认不启用（写工作区覆盖，其它工作区不受影响）"
          : "打开：仅此工作区默认启用（写工作区覆盖）";
  return (
    <li className={active ? "skp-row-wrap skp-row-wrap-active" : "skp-row-wrap"}>
      <button
        type="button"
        role="option"
        aria-selected={active}
        tabIndex={active ? 0 : -1}
        className={active ? "skp-row skp-row-active" : "skp-row"}
        ref={(element) => {
          if (element === null) rowRefs.current.delete(unit.unit);
          else rowRefs.current.set(unit.unit, element);
        }}
        onClick={() => onSelect(unit)}
        onKeyDown={(event) => onKeyDown(event, unit.unit)}
      >
        <span className="skp-row-name">
          <span className={checked ? "skp-dot skp-dot-enabled" : "skp-dot skp-dot-hollow"} aria-hidden="true" />
          <span className="skp-sr-only">{checked ? "默认已启用" : "默认已关闭"}</span>
          <span className="skp-row-title" title={unit.name}>
            {unit.name}
          </span>
        </span>
        <span className="skp-row-meta">
          <span
            className={unitTagClass(unit)}
            title={unit.kind === "unattributed" ? "来源未识别：不是宿主内置工具" : "插件运行时注册（非 MCP）"}
          >
            {unit.kind === "unattributed" ? "未识别" : "插件"}
          </span>
          <span className="skp-tag skp-tag-flat">{unit.toolCount} 个工具</span>
          {visibilityMeta}
        </span>
      </button>
      {/* v21 UX 修订：全局视图行尾不再有单开关（默认在「可见范围」里按工作区配）；
          工作区视图保留默认开关 = 本工作区覆盖。 */}
      {scope === "workspace" && (
        <label className="skp-row-toggle" title={switchTitle}>
          <span className="skp-row-default-label">{switchLabel}</span>
          <span className="skp-switch">
            <input
              type="checkbox"
              role="switch"
              aria-label={`默认启用 ${unit.name}`}
              checked={checked}
              disabled={disabled || busy}
              onChange={(event) => onToggle(unit, event.target.checked)}
            />
            <span className="skp-switch-track" />
          </span>
        </label>
      )}
    </li>
  );
});

/**
 * Tools 域视图：两栏（插件列表 + 详情/只读工具清单）。
 *
 * @param query 根组件头部搜索框的值（按插件名 / 工具名 / 工具说明本地过滤）。
 * @param workspace 当前工作区（undefined = 全局视图；v21 起有工作区维度）。
 * @param projects 全部已知工作区（可见性标签 / 弹层 / 每工作区默认用）。
 */
export function ToolsView({
  api,
  workspace,
  projects = [],
  query,
  onCount,
}: {
  api: CapabilityPanelApi;
  workspace?: string;
  /** 全部已知工作区；旧调用方 / 测试夹具可缺省（按无工作区渲染）。 */
  projects?: Array<{ path: string; title?: string }>;
  query: string;
  /** 数据到达后上报单元总数（域 Tab 计数；全局口径）。 */
  onCount?: (count: number) => void;
}) {
  const [version, setVersion] = useState(0);
  const [selectedUnit, setSelectedUnit] = useState<string | undefined>(undefined);
  const [busyUnit, setBusyUnit] = useState<string | undefined>(undefined);
  const [opError, setOpError] = useState<string | undefined>(undefined);
  const [copied, setCopied] = useState(false);
  /** `tools.inspect` 结果缓存（按 unit；选中时才拉，刷新列表不复用过期数据）。 */
  const [inspectCache, setInspectCache] = useState<Record<string, InspectState>>({});
  /** 手风琴当前展开的工具（同一时间只展开一个）。 */
  const [expandedTool, setExpandedTool] = useState<string | undefined>(undefined);
  const mountedRef = useRef(true);
  const rowRefs = useRef(new Map<string, HTMLElement>());

  const scope: "global" | "workspace" = workspace === undefined ? "global" : "workspace";
  const projectName =
    workspace === undefined ? undefined : (projects.find((project) => project.path === workspace)?.title ?? baseName(workspace));
  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  }, []);

  // v21.3：与 Skills/MCP 同构的缓存列表——切回已访问作用域时同步出旧列表再刷新。
  const {
    data: fetched,
    loading,
    error,
    reload,
  } = useAsyncList(
    async () => {
      // 主面板只看/写全局默认（不传 sessionId）；cwd 由面板 api 的当前作用域决定。
      const [view, visibility, overrides] = await Promise.all([
        api.tools.list(),
        safeGlobalGet(api),
        scope === "workspace" ? safeOverridesGet(api) : Promise.resolve(undefined),
      ]);
      return { view, globalOverrides: visibility, projectOverrides: overrides };
    },
    [api, version, scope, workspace],
    { cacheKey: `tools:${workspace ?? "global"}` },
  );
  const data: ClientToolsList | undefined = fetched?.view;
  const globalOverrides: ClientGlobalOverrides | undefined = fetched?.globalOverrides;
  const projectOverrides: ClientOverrides | undefined = fetched?.projectOverrides;

  const visibilitySets = globalOverrides?.visibility ?? EMPTY_VISIBILITY_SETS;
  /** 某单元的可见性配置（skills/mcp/tools 同构；tools key = unit）。 */
  const visibilityOf = (unit: ClientToolsUnit): ClientCapabilityVisibility | undefined =>
    visibilityEntryOf(visibilitySets, "tools", unit.unit);
  /** 兜底默认是否关闭：legacy `tools-global.json` 已并入行字段 defaultEnabled。 */
  const globalOffOf = (unit: ClientToolsUnit): boolean =>
    !defaultEnabledOf(unit) || globalOverrides?.tools.includes(unit.unit) === true;

  const units = useMemo(() => sortUnits(data?.units ?? []), [data]);
  /** 工作区视图只渲染可见单元（宿主已过滤；这里防御旧宿主 / 脏数据）。 */
  const visibleUnits = useMemo(
    () => (scope === "global" ? units : units.filter((unit) => unit.visibleInWorkspace !== false)),
    [units, scope],
  );
  /** 工作区视图被可见性隐藏的单元数（全局视图恒 0）。 */
  const hiddenCount = scope === "workspace" ? (data?.hiddenCount ?? 0) : 0;

  // 计数回填（搜索不影响计数）；加载中不覆盖。v21：全局口径（Tab 计数不随作用域变）。
  useEffect(() => {
    if (!loading && error === undefined) onCount?.(units.length);
  }, [units.length, loading, error, onCount]);

  // 首次到达 / 当前选中消失时选中第一项（帧 06 默认展开详情）。
  useEffect(() => {
    if (visibleUnits.length === 0) {
      if (selectedUnit !== undefined) setSelectedUnit(undefined);
      return;
    }
    if (selectedUnit !== undefined && visibleUnits.some((unit) => unit.unit === selectedUnit)) return;
    setSelectedUnit(visibleUnits[0]?.unit);
  }, [visibleUnits, selectedUnit]);

  const q = query.trim().toLowerCase();
  const visible = useMemo(
    () =>
      visibleUnits.filter((unit) => {
        if (q === "") return true;
        if (unit.name.toLowerCase().includes(q)) return true;
        return unit.tools.some((tool) => tool.name.toLowerCase().includes(q) || (tool.description ?? "").toLowerCase().includes(q));
      }),
    [visibleUnits, q],
  );

  const selected = visibleUnits.find((unit) => unit.unit === selectedUnit);
  /** true = 宿主仍在解析归属：显示轻量提示，不阻塞开关。 */
  const attributionSettling = data?.attributionSettling === true;

  // 选中单元时懒加载工具 schema（按 unit 缓存）：失败/旧宿主降级为 list 的 name+description。
  const inspectState = selectedUnit === undefined ? undefined : inspectCache[selectedUnit];
  useEffect(() => {
    if (selectedUnit === undefined) return;
    if (inspectCache[selectedUnit] !== undefined) return;
    setInspectCache((prev) => (prev[selectedUnit] !== undefined ? prev : { ...prev, [selectedUnit]: { status: "loading" } }));
    void api.tools
      .inspect({ unit: selectedUnit })
      .then((view) => {
        if (!mountedRef.current) return;
        setInspectCache((prev) => ({ ...prev, [selectedUnit]: { status: "ready", tools: view.tools } }));
      })
      .catch((failure) => {
        if (!mountedRef.current) return;
        setInspectCache((prev) => ({
          ...prev,
          [selectedUnit]: { status: "error", message: String(failure instanceof Error ? failure.message : failure) },
        }));
      });
  }, [api, selectedUnit, inspectCache]);

  // 切换插件时收起展开的工具（避免沿用上一个插件的工具名）。
  useEffect(() => {
    setExpandedTool(undefined);
  }, [selectedUnit]);

  const inspectedTools = inspectState?.status === "ready" ? inspectState.tools : undefined;
  const inspectLoading = inspectState?.status === "loading";
  const inspectError = inspectState?.status === "error" ? inspectState.message : undefined;
  // inspect 未就绪时退回 `tools.list` 的轻量清单（仅名称 + 说明），保证列表不空。
  const displayTools: ClientToolInspectTool[] =
    inspectedTools ??
    (selected?.tools ?? []).map((tool) => ({
      name: tool.name,
      ...(tool.description !== undefined ? { description: tool.description } : {}),
    }));

  /** 当前行的开关勾选态与写路径（按作用域分派）。 */
  const switchStateOf = (unit: ClientToolsUnit) => {
    if (scope === "global") {
      const invisible = isRowInvisible(unit, visibilityOf(unit), projects);
      return { checked: defaultEnabledOf(unit), disabled: unit.lockedReason !== undefined || invisible, invisible };
    }
    const entry = visibilityOf(unit);
    const override = workspaceOverrideOf(projectOverrides, "tools", unit.unit);
    const fallback = workspace === undefined ? true : workspaceDefaultOf(entry, workspace, globalOffOf(unit));
    const checked = override === "on" ? true : override === "off" ? false : fallback;
    return { checked, disabled: unit.lockedReason !== undefined, invisible: false, override };
  };

  /**
   * 写开关：
   *   - 全局视图 → `tools.setGlobalEnabled`（全局兜底默认）；
   *   - 工作区视图 → `overrides.toggle("tools", unit, {enabled})`（项目三态覆盖）。
   */
  const toggleDefault = useCallback(
    async (unit: ClientToolsUnit, next: boolean) => {
      const state = switchStateOf(unit);
      if (state.disabled || busyUnit !== undefined) return;
      setBusyUnit(unit.unit);
      setOpError(undefined);
      try {
        if (scope === "global") {
          await api.tools.setGlobalEnabled({ units: [unit.unit], enabled: next });
        } else {
          const result = await api.overrides.toggle("tools", unit.unit, { enabled: next });
          if (!result.ok) {
            setOpError(result.errors.join("; "));
            return;
          }
        }
      } catch (failure) {
        setOpError(String(failure instanceof Error ? failure.message : failure));
      } finally {
        if (mountedRef.current) setBusyUnit(undefined);
        setVersion((value) => value + 1);
      }
    },
    // switchStateOf 依赖 scope / overrides / projects；重建闭包由这些值驱动。
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [api, busyUnit, scope, projectOverrides, globalOverrides, projects],
  );

  const copyName = async (name: string) => {
    try {
      await navigator.clipboard?.writeText(name);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 1500);
    } catch {
      /* 剪贴板不可用时静默 */
    }
  };

  const focusRow = (unit: string) => {
    const element = rowRefs.current.get(unit);
    element?.focus();
    element?.scrollIntoView({ block: "nearest" });
  };

  const onRowKeyDown = (event: ReactKeyboardEvent<HTMLElement>, unit: string) => {
    if (visible.length === 0) return;
    const index = visible.findIndex((item) => item.unit === unit);
    if (event.key === "ArrowDown" || event.key === "ArrowUp" || event.key === "Home" || event.key === "End") {
      event.preventDefault();
      const next =
        event.key === "Home"
          ? 0
          : event.key === "End"
            ? visible.length - 1
            : event.key === "ArrowDown"
              ? Math.min(visible.length - 1, index + 1)
              : Math.max(0, index - 1);
      const nextUnit = visible[next]?.unit;
      if (nextUnit !== undefined) {
        setSelectedUnit(nextUnit);
        requestAnimationFrame(() => focusRow(nextUnit));
      }
      return;
    }
    if (event.key === "Enter") {
      event.preventDefault();
      setSelectedUnit(unit);
    }
  };

  const listErrors = data?.errors ?? [];

  /** v21.3：稳定回调（配合 `ToolListRow` memo，避免切作用域全量重渲）。 */
  const rowActionsRef = useRef({ setSelectedUnit, toggleDefault, onRowKeyDown });
  rowActionsRef.current = { setSelectedUnit, toggleDefault, onRowKeyDown };
  const stableSelectUnit = useCallback((unit: ClientToolsUnit) => rowActionsRef.current.setSelectedUnit(unit.unit), []);
  const stableToggleUnit = useCallback((unit: ClientToolsUnit, next: boolean) => {
    void rowActionsRef.current.toggleDefault(unit, next);
  }, []);
  const stableRowKeyDown = useCallback(
    (event: ReactKeyboardEvent<HTMLElement>, unit: string) => rowActionsRef.current.onRowKeyDown(event, unit),
    [],
  );

  const listTitle = scope === "global" ? "全局 Tools" : `${projectName ?? "工作区"} · Tools`;
  const listNote = scope === "global" ? "所有工作区" : "仅此工作区";
  const defaultOnCount = visibleUnits.filter((unit) => defaultEnabledOf(unit)).length;

  return (
    <div className="skp-domain">
      {opError !== undefined && <div className="skp-error">{opError}</div>}
      {error !== undefined && <div className="skp-error">读取失败：{error}</div>}
      {error === undefined && listErrors.length > 0 && <div className="skp-error">{listErrors.join("\n")}</div>}
      {loading && data === undefined && <div className="skp-status">加载中…</div>}

      {data !== undefined && error === undefined && (
        <div className="skp-body skp-tools-body">
          {/* 中间列：插件单元列表（v21 起随作用域切换可见集合）。 */}
          <div className="skp-workspace-pane skp-tools-pane">
            <div className="skp-list-head">
              <span className="skp-list-title">{listTitle}</span>
              <span className="skp-group-count" title="当前作用域可见单元数">
                {visibleUnits.length}
              </span>
              <span className="skp-list-note">{listNote}</span>
              {loading && data !== undefined && <span className="skp-refresh-note">刷新中…</span>}
              <span className="skp-detail-head-spacer" />
              <span className="skp-pane-title-note">
                {scope === "global" ? `${defaultOnCount} 默认启用` : "开关写工作区覆盖"}
              </span>
            </div>
            {scope === "global" && (
              <div className="skp-pane-note">全局默认写入统一全局文件 · 所有工作区生效；可见性按工作区控制</div>
            )}
            {scope === "workspace" && (
              <div className="skp-pane-note">只列出本工作区可见的 Tools · 默认开关只作用于本工作区</div>
            )}
            {attributionSettling && <div className="skp-pane-note">来源解析中…</div>}
            {visibleUnits.length === 0 ? (
              <>
                <div className="skp-empty">
                  {listErrors.length > 0
                    ? "当前外壳未提供工具注册表，无法列出 Tools。"
                    : scope === "workspace"
                      ? "本工作区没有可见的 Tools（可在全局视图调整可见范围）。"
                      : "尚未发现 Tools。"}
                </div>
                {hiddenCount > 0 && <div className="skp-pane-note">另有 {hiddenCount} 个能力未对此外工作区开放</div>}
              </>
            ) : visible.length === 0 ? (
              <div className="skp-empty">没有匹配「{query.trim()}」的 Tools。</div>
            ) : (
              <div className="skp-group-scroll">
                <ul className="skp-list" role="listbox" aria-label="Tools">
                  {visible.map((unit) => {
                    const state = switchStateOf(unit);
                    const entry = visibilityOf(unit);
                    return (
                      <ToolListRow
                        key={unit.unit}
                        unit={unit}
                        active={unit.unit === selectedUnit}
                        scope={scope}
                        projectName={projectName}
                        projects={projects}
                        visibilityEntry={entry}
                        globalOff={globalOffOf(unit)}
                        checked={state.checked}
                        disabled={state.disabled}
                        invisible={state.invisible}
                        override={state.override ?? "inherit"}
                        busy={busyUnit === unit.unit}
                        rowRefs={rowRefs}
                        onSelect={stableSelectUnit}
                        onToggle={stableToggleUnit}
                        onKeyDown={stableRowKeyDown}
                      />
                    );
                  })}
                </ul>
                {hiddenCount > 0 && (
                  <div className="skp-pane-note" title="这些单元在全局视图里未被开放给本工作区；请在全局视图的「可见范围」里开启">
                    另有 {hiddenCount} 个能力未对此外工作区开放
                  </div>
                )}
              </div>
            )}
          </div>

          {/* 右侧详情 + 只读工具清单。 */}
          <div className="skp-detail skp-detail-fixed">
            {selected === undefined ? (
              <div className="skp-detail-empty">选择一个插件查看工具清单与参数。</div>
            ) : (
              <div className="skp-detail-card">
                <div className="skp-detail-head">
                  <h3 title={selected.name}>{selected.name}</h3>
                  <span style={HEAD_TAGS_STYLE}>
                    <span className={selected.kind === "unattributed" ? "skp-tag skp-tag-warn" : "skp-tag skp-tag-plugin"}>
                      {selected.kind === "unattributed" ? "未识别" : "插件"}
                    </span>
                    <span className="skp-tag skp-tag-channel" title={selected.attribution.packageName ?? selected.name}>
                      {selected.name}
                    </span>
                  </span>
                  <span className="skp-detail-head-spacer" />
                  <button type="button" className="skp-btn" onClick={() => void copyName(selected.name)}>
                    {copied ? "已复制" : "复制插件名"}
                  </button>
                </div>

                {/* 来源判定 / 注入方式（task-32：按依据显示 + 推测标识）。 */}
                <div className="skp-detail-meta">
                  <span className="skp-detail-meta-item">
                    <span className="skp-detail-meta-strong">来源判定：</span>
                    {attributionLabel(selected)}
                    {attributionDetail(selected) !== undefined ? ` · ${attributionDetail(selected) ?? ""}` : ""}
                  </span>
                  {attributionIsSpeculative(selected) && (
                    <span className="skp-tag skp-tag-warn" title="来源为推测，请核对工具清单">
                      推测
                    </span>
                  )}
                  {(selected.attribution.legacyUnit === true || typeof selected.attribution.legacyUnit === "string") && (
                    <span
                      className="skp-note"
                      title={
                        typeof selected.attribution.legacyUnit === "string"
                          ? `旧版键：${selected.attribution.legacyUnit}`
                          : "旧版持久化键已迁移到新的插件单元"
                      }
                    >
                      旧版键已迁移
                    </span>
                  )}
                  {attributionSettling && <span className="skp-note">来源解析中…</span>}
                  <span className="skp-detail-meta-item">
                    <span className="skp-detail-meta-strong">注入方式：</span>
                    插件运行时注册的非 MCP 工具（不落盘）
                  </span>
                </div>
                {attributionIsSpeculative(selected) && <p className="skp-note skp-note-warn">来源为推测，请核对工具清单</p>}
                {selected.description !== undefined && selected.description.trim().length > 0 && (
                  <p className="skp-note">{selected.description}</p>
                )}

                <div className="skp-note">
                  工具数 {selected.toolCount} · 开关为插件级：关闭后该插件全部工具默认不可用（不改已有对话的显式覆盖）
                </div>

                {/* v21：全局视图的可见性编辑（工作区视图不出现）。 */}
                {scope === "global" && (
                  <dl className="skp-detail-fields">
                    <VisibilityDetailFields
                      api={api}
                      domain="tools"
                      capabilityKey={selected.unit}
                      name={selected.name}
                      entry={visibilityOf(selected)}
                      workspaces={projects}
                      globalOff={globalOffOf(selected)}
                      onSaved={() => setVersion((value) => value + 1)}
                    />
                  </dl>
                )}

                <div className="skp-detail-inspect">
                  <div className="skp-detail-inspect-head">
                    <span className="skp-field-label">工具清单（{selected.toolCount}）</span>
                    <span className="skp-test-stat">
                      {inspectLoading ? "正在读取参数…" : "点击工具查看参数与原始 JSON"}
                    </span>
                  </div>
                  {inspectError !== undefined && (
                    <div className="skp-note">参数不可用：{inspectError}（仍可查看工具名称与说明）</div>
                  )}
                  {displayTools.length === 0 ? (
                    <div className="skp-note">工具清单不可见（该单元当前没有可见工具）。</div>
                  ) : (
                    <div className="skp-tool-accordion" role="list">
                      {displayTools.map((tool) => (
                        <ToolAccordionItem
                          key={tool.name}
                          tool={tool}
                          open={expandedTool === tool.name}
                          onToggle={() => setExpandedTool(expandedTool === tool.name ? undefined : tool.name)}
                        />
                      ))}
                    </div>
                  )}
                </div>

                <p className="skp-note" style={NOTE_STYLE}>
                  插件级开关，不提供单工具开关；无法 restrict 的插件开关置灰并说明原因；宿主内建基础工具不进入本域。
                </p>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
